namespace { constexpr std::uint16_t EM_X86_64=62; constexpr std::uint32_t PT_LOAD=1,PF_X=1,PF_W=2,PF_R=4; constexpr std::size_t EhdrSize=64,PhdrSize=56; struct Segment{std::uint64_t offset,vaddr,filesz,memsz;std::uint32_t flags;}; struct LoadPage{std::uint64_t address;GuestMemory::Permissions permissions;}; bool addOverflow(std::uint64_t a,std::uint64_t b,std::uint64_t& out){if(b>std::numeric_limits<std::uint64_t>::max()-a)return true;out=a+b;return false;} GuestMemory::Permissions permissionsFor(std::uint32_t flags){auto p=GuestMemory::Permissions::None;if(flags&PF_R)p=p|GuestMemory::Permissions::Read;if(flags&PF_W)p=p|GuestMemory::Permissions::Write;if(flags&PF_X)p=p|GuestMemory::Permissions::Execute;return p;} GuestMemory::Permissions combine(GuestMemory::Permissions a,GuestMemory::Permissions b){return static_cast<GuestMemory::Permissions>(static_cast<std::uint8_t>(a)|static_cast<std::uint8_t>(b));} }
bool ElfLoader::loadFile(const std::string& path,GuestMemory& memory,ElfLoadResult& result,std::string& error)const{std::ifstream file(path,std::ios::binary|std::ios::ate);if(!file){error="failed to open ELF file";return false;}auto size=file.tellg();if(size<0){error="failed to determine ELF size";return false;}std::vector<std::uint8_t> image(static_cast<std::size_t>(size));file.seekg(0);if(!image.empty()&&!file.read(reinterpret_cast<char*>(image.data()),static_cast<std::streamsize>(image.size()))){error="failed to read ELF file";return false;}return loadImage(image,memory,result,error);}
bool ElfLoader::loadImage(const std::vector<std::uint8_t>& image,GuestMemory& memory,ElfLoadResult& result,std::string& error)const{result={};error.clear();if(image.size()<EhdrSize||image[0]!=0x7f||image[1]!='E'||image[2]!='L'||image[3]!='F'){error="invalid or truncated ELF header";return false;}if(image[4]!=2||image[5]!=1){error="ELF must be 64-bit little-endian";return false;}const auto rd16=[&](std::size_t o){std::uint16_t v{};std::memcpy(&v,image.data()+o,2);return v;};const auto rd32=[&](std::size_t o){std::uint32_t v{};std::memcpy(&v,image.data()+o,4);return v;};const auto rd64=[&](std::size_t o){std::uint64_t v{};std::memcpy(&v,image.data()+o,8);return v;};const auto machine=rd16(18);const auto entry=rd64(24);const auto phoff=rd64(32);const auto phentsize=rd16(54);const auto phnum=rd16(56);if(machine!=EM_X86_64){error="ELF is not x86-64";return false;}if(phentsize!=PhdrSize){error="unsupported ELF program-header size";return false;}std::uint64_t phend{};if(addOverflow(phoff,static_cast<std::uint64_t>(phnum)*PhdrSize,phend)||phend>image.size()){error="truncated ELF program-header table";return false;}std::vector<Segment> segments;std::vector<LoadPage> pages;bool entryExecutable=false;for(std::uint16_t i=0;i<phnum;++i){const auto base=static_cast<std::size_t>(phoff+static_cast<std::uint64_t>(i)*PhdrSize);if(rd32(base)!=PT_LOAD)continue;const auto flags=rd32(base+4);const auto offset=rd64(base+8);const auto vaddr=rd64(base+16);const auto filesz=rd64(base+32);const auto memsz=rd64(base+40);const auto align=rd64(base+48);if(filesz>memsz||offset>image.size()||filesz>image.size()-offset){error="invalid ELF load segment bounds";return false;}if(memsz==0)continue;if(align&&(align&(align-1))){error="invalid ELF segment alignment";return false;}if(align>1&&(offset%align)!=(vaddr%align)){error="ELF segment alignment mismatch";return false;}std::uint64_t end{};if(addOverflow(vaddr,memsz,end)){error="ELF segment address overflow";return false;}const auto firstPage=vaddr&~(GuestMemory::PageSize-1);const auto lastPage=(end-1)&~(GuestMemory::PageSize-1);const auto permissions=permissionsFor(flags);for(auto address=firstPage;;address+=GuestMemory::PageSize){auto it=std::find_if(pages.begin(),pages.end(),[address](const LoadPage&p){return p.address==address;});if(it==pages.end())pages.push_back({address,permissions});else it->permissions=combine(it->permissions,permissions);if(address==lastPage)break;if(address>std::numeric_limits<std::uint64_t>::max()-GuestMemory::PageSize){error="ELF page range overflow";return false;}}if((flags&PF_X)&&entry>=vaddr&&entry<end)entryExecutable=true;segments.push_back({offset,vaddr,filesz,memsz,flags});}if(segments.empty()){error="ELF contains no PT_LOAD segments";return false;}if(!entryExecutable){error="ELF entry point is not executable";return false;}std::sort(pages.begin(),pages.end(),[](const LoadPage&a,const LoadPage&b){return a.address<b.address;});const auto temp=GuestMemory::Permissions::Read|GuestMemory::Permissions::Write|GuestMemory::Permissions::Execute;std::uint64_t physical=0;for(const auto&page:pages){if(!memory.map(page.address,physical,GuestMemory::PageSize,temp)){error="failed to map ELF page";return false;}physical+=GuestMemory::PageSize;}for(const auto&segment:segments){for(std::uint64_t i=0;i<segment.filesz;++i)if(!memory.write8(segment.vaddr+i,image[static_cast<std::size_t>(segment.offset+i)])){error="failed to copy ELF segment";return false;}for(std::uint64_t i=segment.filesz;i<segment.memsz;++i)if(!memory.write8(segment.vaddr+i,0)){error="failed to zero ELF segment";return false;}}for(const auto&page:pages)if(!memory.protect(page.address,GuestMemory::PageSize,page.permissions)){error="failed to apply ELF permissions";return false;}result.entryPoint=entry;result.machine=machine;result.programHeaders=phnum;return true;}
